import copy


def solve(payload):
    keep = set(payload['keep'])
    def prune(node):
        if node is None:
            return None
        if node['id'] in keep:
            return copy.deepcopy(node)
        children = []
        for child in node['children']:
            result = prune(child)
            if result is not None:
                children.append(result)
        if node['id'] in keep or children:
            return {'id': node['id'], 'children': children}
        return None
    return prune(payload['tree'])

